import{_ as d,o as r,c as a,ag as e}from"./chunks/framework.D2veAa-g.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-操作系统-构件与中间件","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-操作系统-构件与中间件"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/构件与中间件.md","filePath":"综合知识/系统基础/操作系统/构件与中间件.md","lastUpdated":null}'),o={name:"综合知识/系统基础/操作系统/构件与中间件.md"};function n(s,t,l,h,i,b){return r(),a("div",null,[...t[0]||(t[0]=[e('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] COP（面向构件编程）基本支持</li><li>[ ] CORBA 体系结构</li><li>[ ] EJB 三种 Bean 类型</li><li>[ ] J2EE 五种构件模型</li><li>[ ] 中间件基本功能</li><li>[ ] 中间件分类与位置</li><li>[ ] 构件核心特性与标准</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="cop-基本支持" tabindex="-1">COP 基本支持 <a class="header-anchor" href="#cop-基本支持" aria-label="Permalink to &quot;COP 基本支持&quot;">​</a></h3><blockquote><p>🎯 一句话结论：COP 的四个基本支持是<strong>多态性、模块封装性、后期绑定和装载、安全性</strong>。</p></blockquote><p>面向构件编程关注如何构建面向构件的解决方案，需要语言级和运行环境级的支持，核心是让构件能够独立开发、独立部署、动态组装。</p><h3 id="corba-体系结构" tabindex="-1">CORBA 体系结构 <a class="header-anchor" href="#corba-体系结构" aria-label="Permalink to &quot;CORBA 体系结构&quot;">​</a></h3><blockquote><p>🎯 一句话结论：CORBA 的&quot;软总线&quot;是 <strong>ORB（对象请求代理）</strong>，真正干活的是 <strong>Servant（伺服对象）</strong>，协调底层传输的是 <strong>POA（可移植对象适配器）</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>记忆口诀</th></tr></thead><tbody><tr><td><strong>ORB</strong></td><td>对象请求代理，软总线，负责传递请求</td><td>总调度</td></tr><tr><td><strong>Servant</strong></td><td>CORBA 对象的真正实现，完成客户端请求</td><td>干活的</td></tr><tr><td><strong>POA</strong></td><td>在底层传输平台与接收调用并返回结果的对象实现之间协调</td><td>中间协调员</td></tr><tr><td><strong>适配器激活器</strong></td><td>管理 POA 的生命周期</td><td>管 POA 的</td></tr></tbody></table><blockquote><p>CORBA 由 <strong>OMG 组织</strong>制定，支持<strong>跨语言、跨平台</strong>分布式对象集成。</p></blockquote><h3 id="ejb-三种-bean" tabindex="-1">EJB 三种 Bean <a class="header-anchor" href="#ejb-三种-bean" aria-label="Permalink to &quot;EJB 三种 Bean&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>Session Bean（会话交互）→ Entity Bean（数据持久化）→ Message-Driven Bean（异步消息）</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>功能</th><th>关键特征</th></tr></thead><tbody><tr><td><strong>会话型 Bean (Session Bean)</strong></td><td>完成服务端与客户端的交互</td><td>维护短暂会话，会话结束数据消失</td></tr><tr><td><strong>实体型 Bean (Entity Bean)</strong></td><td>数据持久化，简化数据库开发</td><td>持久化数据</td></tr><tr><td><strong>消息驱动 Bean (Message-Driven Bean)</strong></td><td>处理并发和异步访问操作</td><td>⚠️ <strong>异步</strong>接收消息（不是同步！）</td></tr></tbody></table><h3 id="j2ee-五种构件模型" tabindex="-1">J2EE 五种构件模型 <a class="header-anchor" href="#j2ee-五种构件模型" aria-label="Permalink to &quot;J2EE 五种构件模型&quot;">​</a></h3><blockquote><p>🎯 一句话结论：J2EE 的五种构件模型是 <strong>Applet、Servlet、JSP、EJB、Application Client</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>构件</th><th>运行位置</th></tr></thead><tbody><tr><td>Applet</td><td>客户端浏览器</td></tr><tr><td>Application Client</td><td>客户端</td></tr><tr><td>Servlet</td><td>服务端</td></tr><tr><td>JSP</td><td>服务端</td></tr><tr><td>EJB</td><td>服务端业务逻辑</td></tr></tbody></table><p>⚠️ 常见混淆：JNDI、IIOP、RMI 是<strong>通信协议/API</strong>，不是构件模型；JDBC 是数据库 API；JCA 是连接器架构。</p><h3 id="中间件基本功能" tabindex="-1">中间件基本功能 <a class="header-anchor" href="#中间件基本功能" aria-label="Permalink to &quot;中间件基本功能&quot;">​</a></h3><blockquote><p>🎯 一句话结论：中间件的三大基本功能 — <strong>连接和通信</strong>、<strong>交易管理机制</strong>（事务一致性）、<strong>负载均衡和高可用性</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>连接和通信</td><td>为客户端和服务器之间提供连接和通信</td></tr><tr><td>交易管理机制</td><td>保证交易的一致性</td></tr><tr><td>负载均衡和高可用性</td><td>提供应用的负载均衡和高可用性</td></tr></tbody></table><p><strong>中间件位置</strong>：操作系统之上、应用软件之下（OS → 中间件 → 应用）。</p><h3 id="中间件分类" tabindex="-1">中间件分类 <a class="header-anchor" href="#中间件分类" aria-label="Permalink to &quot;中间件分类&quot;">​</a></h3><blockquote><p>🎯 一句话结论：通信中间件实现<strong>跨平台通信</strong>，事务中间件实现<strong>并发事务处理</strong>，Web 服务器中间件提供 <strong>Web 运行时容器</strong>（非数据加密）。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>主要功能</th><th>示例</th></tr></thead><tbody><tr><td>通信（消息）中间件</td><td>保证系统在不同平台之间通信</td><td>—</td></tr><tr><td>事务中间件</td><td>并发事务处理</td><td>—</td></tr><tr><td>Web 服务器中间件</td><td>提供 Web 应用的运行时环境</td><td><strong>Tomcat</strong></td></tr><tr><td>安全中间件</td><td>加密和认证</td><td>—</td></tr></tbody></table><p>⚠️ 易错：Tomcat 是 Web 服务器中间件（提供运行时容器），不是做数据加密的。</p><h3 id="构件核心特性" tabindex="-1">构件核心特性 <a class="header-anchor" href="#构件核心特性" aria-label="Permalink to &quot;构件核心特性&quot;">​</a></h3><blockquote><p>🎯 一句话结论：构件是<strong>自包容</strong>的程序集，<strong>必须通过接口访问</strong>，<strong>不能直接操作内部</strong>，包含一组需要<strong>同时部署</strong>的原子构件。</p></blockquote><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>自包容</td><td>构件是自包容的程序集</td></tr><tr><td>接口访问</td><td>构件必须通过接口访问，封装内部实现</td></tr><tr><td>可重用</td><td>构件具有可重用性</td></tr><tr><td>部署</td><td>构件可单独部署，原子构件不能单独部署</td></tr><tr><td>不可直接操作内部</td><td>❌ 不能直接操作构件内部实现</td></tr></tbody></table><h3 id="构件三大标准对比" tabindex="-1">构件三大标准对比 <a class="header-anchor" href="#构件三大标准对比" aria-label="Permalink to &quot;构件三大标准对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>标准</th><th>制定组织</th><th>特点</th></tr></thead><tbody><tr><td><strong>CORBA</strong></td><td>OMG</td><td>跨语言、跨平台分布式对象集成</td></tr><tr><td><strong>COM/DCOM</strong></td><td>Microsoft</td><td>Windows 平台构件标准</td></tr><tr><td><strong>EJB</strong></td><td>Sun/Oracle</td><td>Java 企业级构件</td></tr></tbody></table>',30)])])}const u=d(o,[["render",n]]);export{c as __pageData,u as default};
